:root {
  --bg: #f4f1ea;
  --card-bg: #ffffff;
  --primary: #2a5d6e;
  --accent: #e07a5f;
  --text: #2b2b2b;
  --muted: #6b6b6b;
  --border: #d9d4cb;
  --focus: #e07a5f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
  padding: 32px;
  width: 100%;
  max-width: 480px;
}

h1 {
  font-size: 1.75rem;
  color: var(--primary);
  margin-bottom: 4px;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--muted);
  margin-bottom: 24px;
  font-size: 0.95rem;
}

.control-group {
  margin-bottom: 24px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--primary);
}

.input-row {
  display: flex;
  gap: 12px;
  align-items: center;
  flex-wrap: wrap;
}

input[type="range"] {
  flex: 1 1 140px;
  accent-color: var(--primary);
  height: 32px;
  cursor: pointer;
}

input[type="number"] {
  width: 80px;
  padding: 8px 10px;
  font-size: 1rem;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--card-bg);
  color: var(--text);
  transition: border-color 0.15s, box-shadow 0.15s;
}

input[type="number"]:hover {
  border-color: var(--primary);
}

input[type="number"]:focus-visible {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(224, 122, 95, 0.35);
}

input[type="number"]:active {
  border-color: var(--accent);
}

.ingredient-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.ingredient-list li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 12px 16px;
  background: #faf8f4;
  border-radius: 10px;
  border-left: 4px solid var(--accent);
  transition: background 0.15s;
}

.ingredient-list li:hover {
  background: #f3efe8;
}

.ingredient-name {
  font-weight: 500;
}

.ingredient-amount {
  font-variant-numeric: tabular-nums;
  color: var(--primary);
  font-weight: 600;
  white-space: nowrap;
  margin-left: 12px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 20px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .input-row {
    gap: 8px;
  }
  input[type="number"] {
    width: 70px;
  }
}

(function () {
  'use strict';

  var BASE_SERVINGS = 4;
  var recipe = [
    { name: 'Flour', amount: 200 },
    { name: 'Sugar', amount: 100 },
    { name: 'Butter', amount: 80 },
    { name: 'Eggs', amount: 2 },
    { name: 'Milk', amount: 150 }
  ];

  var servingsRange = document.getElementById('servings-range');
  var servingsNumber = document.getElementById('servings');
  var list = document.getElementById('ingredient-list');

  function scaleAmount(amount, targetServings) {
    var scaled = (amount / BASE_SERVINGS) * targetServings;
    return Math.round(scaled * 10) / 10;
  }

  function render(servings) {
    var html = '';
    for (var i = 0; i < recipe.length; i++) {
      var item = recipe[i];
      var scaled = scaleAmount(item.amount, servings);
      html += '<li>' +
        '<span class="ingredient-name">' + item.name + '</span>' +
        '<span class="ingredient-amount">' + scaled + '</span>' +
        '</li>';
    }
    list.innerHTML = html;
  }

  function clamp(value) {
    var n = parseInt(value, 10);
    if (isNaN(n)) return 4;
    return Math.min(12, Math.max(1, n));
  }

  function syncInputs(value) {
    var v = clamp(value);
    servingsRange.value = v;
    servingsNumber.value = v;
    render(v);
  }

  servingsRange.addEventListener('input', function () {
    syncInputs(servingsRange.value);
  });

  servingsNumber.addEventListener('input', function () {
    syncInputs(servingsNumber.value);
  });

  servingsNumber.addEventListener('blur', function () {
    syncInputs(servingsNumber.value);
  });

  // Initial render
  syncInputs(servingsNumber.value);
})();
